/// The discovery document standard JWT libraries configure themselves from. Orvano is not an OpenID provider;
/// this exists so tools that take an issuer URL find the keys. Its names are the standard snake case ones.
final class OpenIdConfiguration {
  /// Creates a [OpenIdConfiguration].
  const OpenIdConfiguration({
    required this.issuer,
    required this.jwksUri,
    required this.idTokenSigningAlgValuesSupported,
    required this.subjectTypesSupported,
    required this.responseTypesSupported,
  });

  /// Decodes a [OpenIdConfiguration] from JSON.
  factory OpenIdConfiguration.fromJson(
    Map<String, dynamic> json,
  ) => OpenIdConfiguration(
    issuer: json['issuer'] as String,
    jwksUri: json['jwks_uri'] as String,
    idTokenSigningAlgValuesSupported:
        (json['id_token_signing_alg_values_supported'] as List<dynamic>)
            .map((e) => e as String)
            .toList(),
    subjectTypesSupported: (json['subject_types_supported'] as List<dynamic>)
        .map((e) => e as String)
        .toList(),
    responseTypesSupported: (json['response_types_supported'] as List<dynamic>)
        .map((e) => e as String)
        .toList(),
  );

  /// The issuer, the `iss` of every access token of the project.
  final String issuer;

  /// Where the project's JWKS lives.
  final String jwksUri;

  /// Always `["ES256"]`.
  final List<String> idTokenSigningAlgValuesSupported;

  /// Always `["public"]`.
  final List<String> subjectTypesSupported;

  /// Always `["token"]`.
  final List<String> responseTypesSupported;

  /// Encodes this [OpenIdConfiguration] as JSON.
  Map<String, dynamic> toJson() => {
    'issuer': issuer,
    'jwks_uri': jwksUri,
    'id_token_signing_alg_values_supported': idTokenSigningAlgValuesSupported,
    'subject_types_supported': subjectTypesSupported,
    'response_types_supported': responseTypesSupported,
  };
}

