/// An active session of a user: one signed in device or browser.
final class Session {
  /// Creates a [Session].
  const Session({
    required this.id,
    required this.createdAt,
    required this.lastRefreshedAt,
    this.userAgent,
    this.sdk,
    this.ipAddress,
    required this.current,
    required this.method,
    this.provider,
    required this.aal,
    required this.amr,
  });

  /// Decodes a [Session] from JSON.
  factory Session.fromJson(Map<String, dynamic> json) => Session(
    id: json['id'] as String,
    createdAt: DateTime.parse(json['createdAt'] as String),
    lastRefreshedAt: DateTime.parse(json['lastRefreshedAt'] as String),
    userAgent: json['userAgent'] == null ? null : json['userAgent'] as String,
    sdk: json['sdk'] == null ? null : json['sdk'] as String,
    ipAddress: json['ipAddress'] == null ? null : json['ipAddress'] as String,
    current: json['current'] as bool,
    method: SessionMethod.fromJson(json['method'] as String),
    provider: json['provider'] == null
        ? null
        : OAuthProvider.fromJson(json['provider'] as String),
    aal: (json['aal'] as num).toInt(),
    amr: (json['amr'] as List<dynamic>).map((e) => e as String).toList(),
  );

  /// The session ID.
  final String id;

  /// When the user signed in.
  final DateTime createdAt;

  /// When the session last traded its refresh token.
  final DateTime lastRefreshedAt;

  /// The user agent that signed in, at most 512 characters; null when none was sent.
  final String? userAgent;

  /// The SDK that signed in, from `X-Orvano-SDK`; null when none was sent.
  final String? sdk;

  /// The IP address last seen for the session; null when unknown.
  final String? ipAddress;

  /// Whether this is the session making the call.
  final bool current;

  /// How the session began.
  final SessionMethod method;

  /// The provider of an `oauth` or `id_token` session; null for every other method.
  final OAuthProvider? provider;

  /// How strongly the session signed in: 1 for one factor, 2 once a second factor or a passkey was verified on it. Also
  /// the access token's `aal` claim.
  final int aal;

  /// The ways the user proved who they are on this session, sorted: `pwd`, `email`, `fed`, `otp`, `rec`, `hwk`, `swk`,
  /// `user`, and `mfa` (whenever `aal` is 2). Also the access token's `amr` claim.
  final List<String> amr;

  /// Encodes this [Session] as JSON.
  Map<String, dynamic> toJson() => {
    'id': id,
    'createdAt': createdAt.toUtc().toIso8601String(),
    'lastRefreshedAt': lastRefreshedAt.toUtc().toIso8601String(),
    'userAgent': userAgent,
    'sdk': sdk,
    'ipAddress': ipAddress,
    'current': current,
    'method': method.value,
    'provider': switch (provider) {
      final v? => v.value,
      null => null,
    },
    'aal': aal,
    'amr': amr,
  };
}

