  /// Creates a [SessionTokens].
  const SessionTokens({
    required this.accessToken,
    required this.accessTokenExpiresAt,
    required this.refreshToken,
    required this.refreshTokenExpiresAt,
    required this.sessionId,
  });

  /// Decodes a [SessionTokens] from JSON.
